layouts.css:
/* Source: https://admintnb.com/sticker/gv-2/ — 197 × 285 mm, one popup per A4.
   Source background uses contain; pixel offsets remain at CSS's 96 dpi.
   A5 is scaled uniformly by NCN's existing paperSize()/renderDocument(). */
.ncn-gv2-content{width:197mm;margin:0 auto;padding-top:3mm;text-align:center}
.ncn-gv2-frame{width:197mm;height:285mm;position:relative;overflow:hidden;background-image:url('/assets/ncn-popup/media/gv2-c58265ed88eabe63.png');background-position:center;background-size:contain;background-repeat:no-repeat;break-inside:avoid;page-break-inside:avoid}
.ncn-gv2-frame input[type=text]{position:absolute;left:0;width:100%;margin:0;padding:0;border:0;outline:0;box-shadow:none;border-radius:0;text-align:center;background:transparent;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#000;-webkit-text-fill-color:#000;cursor:default}
.ncn-gv2-frame .gv2-name{font-family:'ncn-gv2-cafeta',Arial,sans-serif;font-size:35px;top:700px;height:50px;line-height:55px;font-weight:400;}
.ncn-gv2-frame .gv2-old{font-family:'ncn-gv2-colossalis',Arial,sans-serif;font-size:98px;top:800px;height:98px;line-height:98px;text-decoration:line-through;}
.ncn-gv2-frame .gv2-new{font-family:'ncn-gv2-colossalis',Arial,sans-serif;font-size:125px;top:910px;height:125px;line-height:125px;font-weight:700;}
.ncn-gv2-frame .gv2-extra1{font-family:'ncn-gv2-colossalis',Arial,sans-serif;font-size:55px;top:490px;height:60px;line-height:70px;font-weight:400;}
.ncn-gv2-frame .gv2-extra2{font-family:'ncn-gv2-colossalis',Arial,sans-serif;font-size:92px;top:565px;height:100px;line-height:110px;font-weight:400;}

